// Embed every data/*.json.gz clip into src/generated/clips.ts as base64 (inlined by the build).
import { readdirSync, readFileSync, writeFileSync, mkdirSync } from "node:fs";
import { join } from "node:path";

const dir = process.argv[2] ?? "data";
const files = readdirSync(dir).filter((f) => f.endsWith(".json.gz")).sort();
const items = files.map((f) => ({ name: f, b64: readFileSync(join(dir, f)).toString("base64") }));
mkdirSync("src/generated", { recursive: true });
writeFileSync(
  "src/generated/clips.ts",
  "// generated by scripts/embed.mjs; do not edit\n" +
    `export const EMBEDDED: { name: string; b64: string }[] = ${JSON.stringify(items)};\n`,
);
console.log(`embedded ${items.length} clips`);
